def transform(grid):
    from collections import Counter
    if not grid: return []
    rows = len(grid)
    cols = len(grid[0])

    counts = Counter(cell for row in grid for cell in row)
    background = max(counts, key=counts.get)

    max_area = 0
    best_rect = None

    # Iterate through all possible rectangles
    for r1 in range(rows):
        for c1 in range(cols):
            for r2 in range(r1, rows):
                for c2 in range(c1, cols):
                    # Check area first to optimize
                    area = (r2 - r1 + 1) * (c2 - c1 + 1)
                    if area <= max_area:
                        continue

                    color = grid[r1][c1]
                    if color == background:
                        continue

                    valid = True
                    for r in range(r1, r2+1):
                        for c in range(c1, c2+1):
                            if grid[r][c] != color:
                                valid = False
                                break
                        if not valid:
                            break

                    if valid:
                        max_area = area
                        best_rect = (color, r1, r2, c1, c2)

    result = [[background] * cols for _ in range(rows)]
    if best_rect:
        color, r1, r2, c1, c2 = best_rect
        for r in range(r1, r2+1):
            for c in range(c1, c2+1):
                result[r][c] = color
    return result
